pub struct NativeChronoCache<K: Hash + Eq, V> {
  data: ChronoCache<K, V>,
}

impl<K: Hash + Eq + Send + Sync, V: Clone + Send + Sync> Default for NativeChronoCache<K, V> {
  fn default() -> Self {
    Self::new()
  }
}

impl<K: Hash + Eq + Send + Sync, V: Clone + Send + Sync> NativeChronoCache<K, V> {
  pub fn new() -> Self {
    NativeChronoCache { data: ChronoCache::new() }
  }
}

#[async_trait::async_trait]
impl<K: Hash + Eq + Send + Sync, V: Clone + Send + Sync> Cache for NativeChronoCache<K, V> {
  type Key = K;
  type Value = V;

  async fn set<'a>(&'a self, key: K, value: V, ttl: NonZeroU64) -> anyhow::Result<V> {
    self.data.insert(key, value.clone(), ttl);
    Ok(value)
  }

  async fn get<'a>(&'a self, key: &'a K) -> anyhow::Result<V> {
    self.data.get(key).ok_or(anyhow::anyhow!("key not found"))
  }
}
