  }

  let key = ctx
    .graphql_ctx
    .args
    .iter()
    .map(|(key, value)| {
      let mut hasher = hasher.clone();
      key.hash(&mut hasher);
      helpers::value::hash(value.as_value(), &mut hasher);
      hasher.finish()
    })
    .fold(hasher.finish(), |acc, val| acc ^ val);

